		return ""
	}
	for _, wt := range wts {
		if wt.Branch == branch {
			return wt.Path
		}
	}
	return ""
}

// nameFromBranch derives a short worktree name from a branch ref.
// Takes the last segment after "/" and strips the remote prefix if present.
//
//	"origin/user/fix-login" → "fix-login"
//	"user/fix-login"        → "fix-login"
//	"fix-login"             → "fix-login"
func nameFromBranch(ref, remote string) string {
	parts := strings.Split(ref, "/")
	name := parts[len(parts)-1]
	return strings.TrimPrefix(name, remote+"/")
}

// createWorktreeFromRemote handles the common flow for checking out a remote
// branch into a new worktree: check if it already exists, create, and
// optionally run init. Callers fetch first. Used by `wt new --from`, `wt pull`
// and `wt pr`.
func createWorktreeFromRemote(ctx *cmdContext, name, remoteBranch string, doInit bool) error {
	wtPath := ctx.worktreePath(name)

	if isDir(wtPath) {
		return fmt.Errorf("worktree already exists: %s\n   Use wt switch %s to switch to it", wtPath, name)
	}

	localBranch := strings.TrimPrefix(remoteBranch, ctx.Config.Remote+"/")
	remoteRef := ctx.Config.Remote + "/" + localBranch

	fmt.Println("Creating worktree from existing branch…")
	fmt.Printf("  Directory: %s\n", wtPath)
	fmt.Printf("  Branch: %s\n", localBranch)
	fmt.Println()

	var err error
	if git.BranchExists(localBranch) {
		err = git.AddWorktreeFromExisting(wtPath, localBranch)
	} else {
		err = git.AddWorktreeFromRemote(wtPath, localBranch, remoteRef)
	}
	if err != nil {
		return fmt.Errorf("failed to create worktree: %w", err)
	}

	fmt.Println()
	ui.Success("Created worktree")
	fmt.Println()

	if doInit {
		return runInitIn(wtPath, ctx)
	}
	printSwitchHint(name)
	return nil
}

// printSwitchHint prints the next-step command.
func printSwitchHint(name string) {
	fmt.Printf("  → wt switch %s && wt init\n", name)
	ui.PrintWrapperHint()
	ui.PrintCTA("wt switch "+name, "wt init")
}

// validateName rejects worktree names that would break git or hide the
// main checkout from 'wt switch'. Call it before doing any work.
func validateName(ctx *cmdContext, name string) error {
	if strings.HasPrefix(name, "-") {
		return fmt.Errorf("invalid name %q: it can't start with a dash", name)
	}
	if ctx.isBaseBranch(name) || name == ctx.RepoName {
		return fmt.Errorf("invalid name %q: 'wt switch %s' would open this worktree instead of the main checkout\n   Pick another name", name, name)
	}
	if branch := ctx.branchName(name); !git.IsValidBranchName(branch) {
		return fmt.Errorf("invalid name %q: %q is not a valid git branch name", name, branch)
	}
	return nil
}

func newFromBase(ctx *cmdContext, name string) error {
	branch := ctx.branchName(name)
	wtPath := ctx.worktreePath(name)

	if isDir(wtPath) {
		return fmt.Errorf("worktree already exists: %s\n   Use wt switch %s to switch to it", wtPath, name)
	}

	if git.BranchExists(branch) {
		return fmt.Errorf("branch already exists: %s\n   Use wt new --from %s to create a worktree for it\n   Or wt switch %s if the worktree already exists", branch, branch, name)
	}

	fmt.Println("Creating worktree…")
	fmt.Printf("  Directory: %s\n", wtPath)
	fmt.Printf("  Branch: %s (from %s)\n", branch, ctx.Config.BaseBranch)
	fmt.Println()

	// Fetch latest base branch
	spin := ui.NewSpinner(fmt.Sprintf("Fetching %s", ctx.Config.BaseBranch))
	if err := git.Fetch(ctx.Config.Remote, ctx.Config.BaseBranch); err != nil {
		spin.Stop()
		ui.Warn("Fetch failed: %v", err)
	} else {
		spin.Stop()
	}

	if err := git.AddWorktree(wtPath, branch, ctx.baseRef()); err != nil {
		return fmt.Errorf("failed to create worktree: %w", err)
	}

	fmt.Println()
	ui.Success("Created worktree")
	fmt.Println()

	if newDoInit {
		return runInitIn(wtPath, ctx)
	}
	printSwitchHint(name)
	return nil
}
package cmd

import (
	"fmt"
	"strconv"

	"github.com/mvwi/wt/internal/github"
	"github.com/spf13/cobra"
)

var prCmd = &cobra.Command{
	Use:     "pr <number>",
	GroupID: groupWorkflow,
	Short:   "Checkout a PR into a worktree",
	Long: `Fetch a GitHub pull request into its own worktree.

Looks up the PR by number, resolves the branch, and creates a worktree
for it — useful for code review workflows.

Requires the GitHub CLI (gh) to be installed.`,
	Example: `  wt pr 123          Checkout PR #123 into a worktree
  wt pr 123 --init   Checkout + auto-initialize`,
	Args: cobra.ExactArgs(1),
	RunE: runPR,
}

var prDoInit bool

func init() {
	prCmd.Flags().BoolVarP(&prDoInit, "init", "i", false, "run 'wt init' after creating")
	rootCmd.AddCommand(prCmd)
}

func runPR(cmd *cobra.Command, args []string) error {
	if !github.IsAvailable() {
		return fmt.Errorf("gh CLI is required for this command (brew install gh)")
	}

	number, err := strconv.Atoi(args[0])
	if err != nil {
		return fmt.Errorf("invalid PR number: %s", args[0])
	}

	ctx, err := newContext()
	if err != nil {
		return err
	}

	pr, err := github.GetPRByNumber(number)
	if err != nil {
		return fmt.Errorf("failed to fetch PR #%d: %w", number, err)
	}

	if pr.State != "OPEN" {
		return fmt.Errorf("PR #%d is %s", number, pr.State)
	}

	fmt.Printf("PR #%d: %s\n", pr.Number, pr.Title)
	fmt.Println()

	return checkoutPR(ctx, "", pr, prDoInit)
}
package cmd

import (
	"fmt"

	"github.com/mvwi/wt/internal/git"
	"github.com/mvwi/wt/internal/ui"
	"github.com/spf13/cobra"
)

var pullCmd = &cobra.Command{
	Use:     "pull <branch> [name]",
	GroupID: groupWorkflow,
	Short:   "Pull a remote branch into a new worktree",
	Long: `Fetch a remote branch and create a worktree for it.

This is a shorthand for "wt new [name] --from <branch>". If no name is
given, one is derived from the last segment of the branch name.`,
	Example: `  wt pull feature/login       Create worktree from remote branch
  wt pull user/sidebar card   Create worktree named "card" from remote branch
  wt pull feature/login -i    Pull + auto-initialize`,
	Args: cobra.RangeArgs(1, 2),
	RunE: runPull,
}

var pullDoInit bool

func init() {
	pullCmd.Flags().BoolVarP(&pullDoInit, "init", "i", false, "run 'wt init' after creating")
	rootCmd.AddCommand(pullCmd)
}

func runPull(cmd *cobra.Command, args []string) error {
	ctx, err := newContext()
	if err != nil {
		return err
	}

	branch := args[0]
	var name string
	if len(args) > 1 {
		name = args[1]
	}

	// Fetch to get latest refs
	spin := ui.NewSpinner("Fetching latest refs")
	if err := git.FetchAll(ctx.Config.Remote); err != nil {
		spin.Stop()
		ui.Warn("Fetch failed: %v", err)
	} else {
		spin.Stop()
	}

	ref, isRemote, err := git.ResolveBranch(branch, ctx.Config.Remote)
	if err != nil {
		return err
	}

	if name == "" {
		name = nameFromBranch(ref, ctx.Config.Remote)
	}

	if isRemote {
		return createWorktreeFromRemote(ctx, name, ref, pullDoInit)
	}

	// Local branch — same path as wt new --from with a local branch
	wtPath := ctx.worktreePath(name)

	if isDir(wtPath) {
		return fmt.Errorf("worktree already exists: %s\n   Use wt switch %s to switch to it", wtPath, name)
	}

	fmt.Println("Creating worktree from existing branch…")
	fmt.Printf("  Directory: %s\n", wtPath)
	fmt.Printf("  Branch: %s\n", ref)
	fmt.Println()

	if err := git.AddWorktreeFromExisting(wtPath, ref); err != nil {
		return fmt.Errorf("failed to create worktree: %w", err)
	}

	fmt.Println()
	ui.Success("Created worktree")
	fmt.Println()

	if pullDoInit {
		return runInitIn(wtPath, ctx)
	}
	printSwitchHint(name)
	return nil
}

