package ui

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/fatih/color"
	"github.com/mattn/go-isatty"
)

// Color shortcuts — matches the fish script's set_color calls.
var (
	Green   = color.New(color.FgGreen).SprintFunc()
	Yellow  = color.New(color.FgYellow).SprintFunc()
	Red     = color.New(color.FgRed).SprintFunc()
	Blue    = color.New(color.FgBlue).SprintFunc()
	Cyan    = color.New(color.FgCyan).SprintFunc()
	Magenta = color.New(color.FgMagenta).SprintFunc()
	Dim     = color.New(color.FgHiBlack).SprintFunc()
	Bold    = color.New(color.Bold).SprintFunc()

	GreenF  = color.New(color.FgGreen).PrintfFunc()
	YellowF = color.New(color.FgYellow).PrintfFunc()
	BlueF   = color.New(color.FgBlue).PrintfFunc()
	CyanF   = color.New(color.FgCyan).PrintfFunc()
	DimF    = color.New(color.FgHiBlack).PrintfFunc()
)

// Glyphs used throughout the UI.
const (
	Current   = "●"
	Pending   = "◐"
	Pass      = "✓"
	Fail      = "✗"
	ArrowDown = "⇣"
	ArrowUp   = "⇡"
	PushUp    = "⬆"
	Dash      = "—"
	NoReview  = "○"
)

// YesFlag is set by the root command's --yes persistent flag.
// When true, Confirm() skips the interactive prompt and returns true.
// It never answers ConfirmDiscard(); that takes --force.
var YesFlag bool

// Truncate shortens a string to max runes, adding "…" if truncated.
func Truncate(s string, max int) string {
	runes := []rune(s)
	if len(runes) <= max {
		return s
	}
	if max <= 1 {
		return "…"
	}
	return string(runes[:max-1]) + "…"
}

// Confirm prompts the user with a y/n question.
// defaultYes: if true, pressing Enter means yes (Y/n); if false, means no (y/N).
// When stdin is not a terminal, returns defaultYes without prompting.
// Unrecognized input re-prompts until a valid answer is given.
func Confirm(message string, defaultYes bool) bool {
	if YesFlag {
		return true
	}
	if !IsTTY() {
		return defaultYes
	}
	return ask(message, defaultYes)
}

// ErrNeedsForce is returned by ConfirmDiscard when it may not ask.
var ErrNeedsForce = errors.New("won't discard work without --force\n   Re-run with --force to discard it")

// ConfirmDiscard asks before throwing away uncommitted changes or commits.
// Only force answers it: --yes does not, and with no terminal (or under
// --yes) it returns ErrNeedsForce so the command exits non-zero.
func ConfirmDiscard(message string, force bool) (bool, error) {
	if force {
		return true, nil
	}
	if YesFlag || !IsTTY() {
		return false, ErrNeedsForce
	}
	return ask(message, false), nil
}

func ask(message string, defaultYes bool) bool {
	hint := "y/N"
	if defaultYes {
		hint = "Y/n"
	}

	reader := bufio.NewReader(os.Stdin)
	for {
		fmt.Printf("%s [%s] ", message, hint)
		input, err := reader.ReadString('\n')
		if err != nil {
			return defaultYes
		}
		input = strings.TrimSpace(strings.ToLower(input))

		switch input {
		case "":
			return defaultYes
		case "y", "yes":
			return true
		case "n", "no":
			return false
		default:
			fmt.Println("Answer y or n.")
		}
	}
}

// PrintCdHint tells the shell wrapper to cd into the given path.
// When WT_CD_FILE is set (by the shell wrapper), writes the path to that file.
// Otherwise prints a hint so the user knows to cd manually.
func PrintCdHint(path string) {
	if cdFile := os.Getenv("WT_CD_FILE"); cdFile != "" {
		if err := os.WriteFile(cdFile, []byte(path), 0600); err != nil {
			fmt.Printf("  → cd %s\n", shellQuote(path))
		}
		return
	}
	fmt.Printf("  → cd %s\n", shellQuote(path))
	PrintWrapperHint()
}

var wrapperHintShown bool

// PrintWrapperHint tells a human at a terminal how to load the shell wrapper,
// once per run. It stays quiet when the wrapper is loaded or stdout is not a TTY.
func PrintWrapperHint() {
	if wrapperHintShown || os.Getenv("WT_CD_FILE") != "" || !IsTTY() {
		return
	}
	wrapperHintShown = true
	DimF("  wt can't cd for you: the shell wrapper isn't loaded. %s\n", wrapperSetup(os.Getenv("SHELL")))
}

// wrapperSetup returns the line that loads the wrapper for the given $SHELL.
func wrapperSetup(shell string) string {
	switch filepath.Base(shell) {
	case "fish":
		return "Add to ~/.config/fish/config.fish:\n    wt init-shell fish | source"
	case "zsh":
		return "Add to ~/.zshrc:\n    eval \"$(wt init-shell zsh)\""
	case "bash":
		return "Add to ~/.bashrc:\n    eval \"$(wt init-shell bash)\""
	}
	return "See: wt init-shell --help"
}

// shellQuote wraps a path in single quotes if it contains shell-special characters.
func shellQuote(s string) string {
	if !strings.ContainsAny(s, " \t\n'\"\\$`|&;<>(){}[]!*?~") {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

// Error prints an error message with ✗ prefix to stderr.
func Error(format string, args ...any) {
	fmt.Fprintf(os.Stderr, Red("✗")+" "+format+"\n", args...)
}

// Success prints a success message with ✓ prefix.
func Success(format string, args ...any) {
	fmt.Printf(Green("✓")+" "+format+"\n", args...)
}

// Warn prints a warning message to stderr.
func Warn(format string, args ...any) {
	fmt.Fprintf(os.Stderr, Yellow("⚠")+"  "+format+"\n", args...)
}

// Info prints a regular message.
func Info(format string, args ...any) {
	fmt.Printf(format+"\n", args...)
}

// IsTTY reports whether stdout is connected to a terminal.
func IsTTY() bool {
	return isatty.IsTerminal(os.Stdout.Fd()) || isatty.IsCygwinTerminal(os.Stdout.Fd())
}

// ClearLines moves the cursor up n lines and clears each one.
// Used by wt watch to redraw the live status table in-place.
// No-op when stdout is not a terminal.
func ClearLines(n int) {
	if !IsTTY() {
		return
	}
	for range n {
		fmt.Print("\033[A\033[K")
	}
}

// Header prints a dim section header (like "WORKTREES").
func Header(text string) {
	fmt.Println()
	DimF("  %s\n", text)
}

// PrintCTA prints machine-readable call-to-action suggestions for agent consumers.
// Only emits output when stdout is not a TTY — human terminal output is unaffected.
// Format: "cta: cmd1 | cmd2"
func PrintCTA(cmds ...string) {
	if len(cmds) == 0 || IsTTY() {
		return
	}
	fmt.Printf("cta: %s\n", strings.Join(cmds, " | "))
}

// CISummary condenses CI check counts into one short cell: "✗ 2/36" when any
// fail, "◐ 3/36" when any are pending, otherwise "✓ 36". Returns "" when
// there are no checks. Callers pick the color.
func CISummary(pass, fail, pending, total int) string {
	switch {
	case total == 0:
		return ""
	case fail > 0:
		return fmt.Sprintf("%s %d/%d", Fail, fail, total)
	case pending > 0:
		return fmt.Sprintf("%s %d/%d", Pending, pending, total)
	}
	return fmt.Sprintf("%s %d", Pass, pass)
}
package ui

import (
	"fmt"
	"sync"
	"time"
)

// Spinner shows an animated wave indicator for long-running operations.
// The animation uses block element characters rendered as a 3-bar equalizer.
type Spinner struct {
	done    chan struct{}
	stopped chan struct{}
	once    sync.Once
}

// Wave frames: 3 bars that rise and fall in sequence.
var waveFrames = []string{
	"▃ ▁ ▃",
	"▅ ▂ ▁",
	"▇ ▅ ▂",
	"█ ▇ ▅",
	"▇ █ ▇",
	"▅ ▇ █",
	"▂ ▅ ▇",
	"▁ ▂ ▅",
}

// NewSpinner starts an animated spinner with the given message (auto-dimmed).
// Call Stop() to clear the spinner line and release resources.
func NewSpinner(message string) *Spinner {
	return newSpinner(Dim(message))
}

// NewSpinnerRich starts a spinner that renders the message as-is, without
// wrapping it in Dim. Use this when the message contains its own ANSI colors.
func NewSpinnerRich(message string) *Spinner {
	return newSpinner(message)
}

func newSpinner(formatted string) *Spinner {
	s := &Spinner{
		done:    make(chan struct{}),
		stopped: make(chan struct{}),
	}

	tty := IsTTY()

	go func() {
		defer close(s.stopped)

		if !tty {
			// Non-TTY: draw nothing, so pipes and logs get only real output.
			<-s.done
			return
		}

		ticker := time.NewTicker(80 * time.Millisecond)
		defer ticker.Stop()

		frame := 0
		for {
			select {
			case <-s.done:
				fmt.Print("\r\033[K")
				return
			case <-ticker.C:
				fmt.Printf("\r\033[K  %s %s", Cyan(waveFrames[frame]), formatted)
				frame = (frame + 1) % len(waveFrames)
			}
		}
	}()

	return s
}

// Stop clears the spinner line and joins the goroutine.
// Safe to call multiple times.
func (s *Spinner) Stop() {
	s.once.Do(func() {
		close(s.done)
		<-s.stopped
	})
}
package cmd

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/mvwi/wt/internal/config"
	"github.com/mvwi/wt/internal/git"
	"github.com/mvwi/wt/internal/ui"
	"github.com/spf13/cobra"
)

// cmdContext holds resolved repo info + config that most commands need.
type cmdContext struct {
	Config       *config.Config
	RepoName     string
	MainWorktree string
	ParentDir    string
	Username     string
}

// newContext builds shared context from the current repo.
func newContext() (*cmdContext, error) {
	if !git.IsInsideRepo() {
		cwd, _ := os.Getwd()
		return nil, fmt.Errorf("not inside a git repository: %s", cwd)
	}
	if git.IsBareRepo() {
		cwd, _ := os.Getwd()
		return nil, fmt.Errorf("%s is a bare repository; wt needs a normal checkout\n   Run wt from a clone with a working tree", cwd)
	}

	mainWT, err := git.MainWorktree()
	if err != nil {
		return nil, err
	}

	repo, err := git.RepoName()
	if err != nil {
		return nil, err
	}

	cfg, err := config.Load(mainWT, repo)
	if err != nil {
		return nil, err
	}

	parentDir, err := git.ParentDir()
	if err != nil {
		return nil, err
	}

	username, err := git.Username()
	if err != nil && cfg.BranchPrefix == nil {
		// Only warn if branch_prefix isn't explicitly configured,
		// since the username is only used as a fallback prefix.
		ui.Warn("Could not determine git username — branches won't have a prefix. Set branch_prefix in .wt.toml or run: git config user.name \"Your Name\"")
	}

	return &cmdContext{
		Config:       cfg,
		RepoName:     repo,
		MainWorktree: mainWT,
		ParentDir:    parentDir,
		Username:     username,
	}, nil
}

// branchName builds a full branch name using config.
func (c *cmdContext) branchName(name string) string {
	return c.Config.EffectiveBranchName(name, c.Username)
}

// worktreeDir builds a worktree directory name using config.
func (c *cmdContext) worktreeDir(name string) string {
	return c.Config.EffectiveWorktreeDir(c.RepoName, name)
}

// worktreePath builds a full worktree path.
func (c *cmdContext) worktreePath(name string) string {
	return c.ParentDir + "/" + c.worktreeDir(name)
}

// baseRef returns the full remote ref for the base branch (e.g., "origin/staging").
func (c *cmdContext) baseRef() string {
	return c.Config.Remote + "/" + c.Config.BaseBranch
}

// shortName returns a worktree's path relative to the worktrees dir, so a
// "feat/foo" worktree shows as "feat/foo", not "foo". Paths outside the
// worktrees dir fall back to their base name.
func (c *cmdContext) shortName(path string) string {
	prefix := c.Config.EffectiveWorktreeDir(c.RepoName, "")
	if rel, err := filepath.Rel(c.ParentDir, path); err == nil && rel != "." && !strings.HasPrefix(rel, "..") {
		return strings.TrimPrefix(strings.TrimPrefix(filepath.ToSlash(rel), filepath.ToSlash(prefix)), "/")
	}
	return strings.TrimPrefix(filepath.Base(path), prefix)
}

// isBaseBranch returns true if the branch is the configured base branch or a common default.
func (c *cmdContext) isBaseBranch(branch string) bool {
	return branch == c.Config.BaseBranch || branch == "main" || branch == "master"
}

// isSubpath returns true if child is a subdirectory of parent.
func isSubpath(child, parent string) bool {
	rel, err := filepath.Rel(parent, child)
	if err != nil {
		return false
	}
	return rel != "." && !strings.HasPrefix(rel, "..") && !filepath.IsAbs(rel)
}

// fileExists returns true if the path exists.
func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// isDir returns true if the path exists and is a directory.
func isDir(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}

// completeWorktreeNames returns a Cobra ValidArgsFunction that suggests worktree short names.
func completeWorktreeNames(_ *cobra.Command, _ []string, toComplete string) ([]string, cobra.ShellCompDirective) {
	ctx, err := newContext()
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}

	worktrees, err := git.ListWorktrees()
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}

	prefix := ctx.Config.EffectiveWorktreeDir(ctx.RepoName, "")
	var names []string
	for _, wt := range worktrees {
		if wt.Path == ctx.MainWorktree {
			continue
		}
		short := strings.TrimPrefix(filepath.Base(wt.Path), prefix)
		if toComplete == "" || strings.HasPrefix(short, toComplete) {
			names = append(names, short)
		}
	}
	return names, cobra.ShellCompDirectiveNoFileComp
}

