package cmd

import (
	"fmt"
	"os"

	"github.com/mvwi/wt/internal/git"
	"github.com/mvwi/wt/internal/github"
	"github.com/mvwi/wt/internal/ui"
	"github.com/spf13/cobra"
)

var closeCmd = &cobra.Command{
	Use:     "close [name]",
	Aliases: []string{"rm"},
	GroupID: groupManage,
	Short:   "Close and clean up a worktree",
	Long: `Close a worktree by removing the directory and deleting the local branch.

Without arguments, closes the current worktree.
With a name, closes the specified worktree.

Safety checks:
  - Asks before discarding uncommitted changes or unpushed commits
    (--yes does not skip this; --force does)
  - Warns if PR is still open
  - Cannot close the main repository worktree`,
	Example: `  wt close                 Close current worktree
  wt close sidebar         Close the "sidebar" worktree
  wt close sidebar --yes   Skip prompts that lose no work
  wt close sidebar --force Discard uncommitted changes and unpushed commits`,
	Args:              cobra.MaximumNArgs(1),
	ValidArgsFunction: completeWorktreeNames,
	RunE:              runClose,
}

var closeForceFlag bool

func init() {
	closeCmd.Flags().BoolVarP(&closeForceFlag, "force", "f", false, "discard uncommitted changes and unpushed commits")
	rootCmd.AddCommand(closeCmd)
}

func runClose(cmd *cobra.Command, args []string) error {
	ctx, err := newContext()
	if err != nil {
		return err
	}

	cwd, err := os.Getwd()
	if err != nil {
		return fmt.Errorf("cannot determine current directory: %w", err)
	}
	worktrees, err := git.ListWorktrees()
	if err != nil {
		return err
	}

	// Determine target
	var targetPath, targetBranch string

	if len(args) > 0 {
		var (
			fuzzy      bool
			resolveErr error
		)
		targetPath, fuzzy, resolveErr = resolveWorktree(ctx, worktrees, args[0])
		if resolveErr != nil {
			return resolveErr
		}
		if targetPath == "" {
			return fmt.Errorf("worktree not found: %s\n   Run wt list to see available worktrees", args[0])
		}
		if fuzzy {
			if !ui.Confirm(fmt.Sprintf("Close %s?", ctx.shortName(targetPath)), false) {
				fmt.Println("Cancelled")
				return nil
			}
		}
	} else {
		// Close current worktree
		if cwd == ctx.MainWorktree || isSubpath(cwd, ctx.MainWorktree) {
			return fmt.Errorf("cannot close the main repository worktree\n   Specify a worktree name: wt close <name>")
		}
		targetPath = cwd
	}

	if targetPath == ctx.MainWorktree {
		return fmt.Errorf("cannot close the main repository worktree")
	}

	targetBranch, _ = git.CurrentBranchIn(targetPath)

	// Safety: uncommitted changes
	if git.HasChangesIn(targetPath) {
		ui.Warn("Worktree has uncommitted changes:")
		short, _ := git.StatusShortIn(targetPath)
		fmt.Println(short)
		fmt.Println()
		if ok, err := ui.ConfirmDiscard("Discard changes and close?", closeForceFlag); !ok {
			return cancelled(err)
		}
	}

	// Safety: unpushed commits
	if unpushed := git.UnpushedCountIn(targetPath); unpushed > 0 {
		ui.Warn("Branch has %d unpushed commit(s)", unpushed)
		if ok, err := ui.ConfirmDiscard("Discard commits and close?", closeForceFlag); !ok {
			return cancelled(err)
		}
	}

	// Safety: open PR
	if github.IsAvailable() && targetBranch != "" {
		pr, _ := github.GetPRForBranch(targetBranch)
		if pr != nil && pr.State == "OPEN" {
			ui.Warn("PR #%d is still open", pr.Number)
			if !ui.Confirm("Close worktree anyway?", false) {
				fmt.Println("Cancelled")
				return nil
			}
		}
	}

	fmt.Printf("Closing worktree: %s\n", targetPath)
	fmt.Printf("Branch: %s\n", targetBranch)
	fmt.Println()

	// Check if we need to cd out before removal
	needsCd := cwd == targetPath || isSubpath(cwd, targetPath)

	// Remove worktree
	if err := git.RemoveWorktree(targetPath); err != nil {
		return fmt.Errorf("failed to remove worktree: %w", err)
	}

	// Our cwd may be gone now, and git refuses to run from a deleted dir.
	if err := os.Chdir(ctx.MainWorktree); err != nil {
		return fmt.Errorf("cannot enter main worktree: %w", err)
	}

	// cd out after successful removal
	if needsCd {
		ui.PrintCdHint(ctx.MainWorktree)
		fmt.Printf("Moved to main repo: %s\n", ctx.MainWorktree)
	}

	// Delete local branch
	branchKept := false
	if targetBranch != "" && git.BranchExists(targetBranch) {
		if err := git.DeleteBranch(targetBranch); err != nil {
			ui.Warn("Could not delete local branch %s: %v", targetBranch, err)
			branchKept = true
		} else {
			ui.Success("Deleted local branch: %s", targetBranch)
		}
	}

	fmt.Println()
	if branchKept {
		ui.Warn("Closed worktree, but branch %s is still there", targetBranch)
	} else {
		ui.Success("Closed worktree")
	}
	ui.PrintCTA("wt list")
	return nil
}

// cancelled ends a command after a declined prompt: exit 0 for a plain "no",
// or the error when the prompt could not be asked.
func cancelled(err error) error {
	if err != nil {
		return err
	}
	fmt.Println("Cancelled")
	return nil
}
package cmd

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/mattn/go-isatty"
	"github.com/mvwi/wt/internal/git"
	"github.com/mvwi/wt/internal/ui"
	"github.com/spf13/cobra"
)

const prevWorktreeStateFile = "wt-prev-worktree"

var switchCmd = &cobra.Command{
	Use:     "switch [name]",
	Aliases: []string{"sw", "cd", "checkout", "co"},
	GroupID: groupWorkflow,
	Short:   "Switch to a worktree",
	Long: `Switch to a different worktree.

Without arguments, opens an interactive picker (requires fzf).
With a name, resolves the worktree using fuzzy matching.
Use "-" to switch back to the previous worktree.

Resolution order:
  1. Exact match: wt-<repo>-<name>
  2. Main repo: 'main', base branch name, or repo name
  3. Branch name: exact match against the git branch
  4. Suffix match: any worktree ending with -<name>
  5. Fuzzy match: worktree or branch containing the search term

If a step matches more than one worktree, wt opens fzf on just those
(or lists them when fzf or a terminal isn't available).`,
	Example: `  wt switch           Interactive picker (requires fzf)
  wt switch sidebar   Switch to "sidebar" worktree (fuzzy match)
  wt switch -         Switch back to previous worktree
  wt switch main      Switch to main repository`,
	Args:              cobra.MaximumNArgs(1),
	ValidArgsFunction: completeWorktreeNames,
	RunE:              runSwitch,
}

func init() {
	rootCmd.AddCommand(switchCmd)
}

func runSwitch(cmd *cobra.Command, args []string) error {
	ctx, err := newContext()
	if err != nil {
		return err
	}

	worktrees, err := git.ListWorktrees()
	if err != nil {
		return err
	}

	cwd, err := os.Getwd()
	if err != nil {
		return fmt.Errorf("cannot determine current directory: %w", err)
	}

	// Handle "wt switch -" — toggle to previous worktree
	if len(args) == 1 && args[0] == "-" {
		return switchPrevious(cwd)
	}

	// No args: interactive fzf picker
	if len(args) == 0 {
		return switchInteractive(ctx, worktrees, cwd)
	}

	return switchByName(ctx, worktrees, cwd, args[0])
}

func switchPrevious(cwd string) error {
	prev, err := git.ReadStateFile(prevWorktreeStateFile)
	if err != nil {
		return fmt.Errorf("no previous worktree to switch to\n   Use wt switch <name> to specify one")
	}

	prev = strings.TrimSpace(prev)
	if !isDir(prev) {
		return fmt.Errorf("previous worktree no longer exists: %s\n   It may have been closed. Run wt list to see available worktrees", prev)
	}

	savePreviousWorktree(cwd)
	ui.PrintCdHint(prev)
	return nil
}

func savePreviousWorktree(cwd string) {
	_ = git.SaveStateFile(prevWorktreeStateFile, cwd)
}

func switchInteractive(ctx *cmdContext, worktrees []git.Worktree, cwd string) error {
	if _, err := exec.LookPath("fzf"); err != nil {
		return fmt.Errorf("no worktree name given, and fzf isn't installed for the picker\n   Run wt switch <name>, or install fzf (brew install fzf)")
	}

	target, err := pickWorktree(ctx, worktrees, cwd, "")
	if err != nil {
		return err
	}
	if target == "" {
		fmt.Println("Cancelled")
		return nil
	}

	savePreviousWorktree(cwd)
	ui.PrintCdHint(target)
	showSwitchSummary(target, ctx)
	return nil
}

// pickWorktree opens fzf over worktrees, starting with query typed in.
// Returns "" when the user cancels.
func pickWorktree(ctx *cmdContext, worktrees []git.Worktree, cwd, query string) (string, error) {
	var lines []string
	for _, wt := range worktrees {
		short := ctx.shortName(wt.Path)
		branch, _ := git.CurrentBranchIn(wt.Path)
		marker := "  "
		if wt.Path == cwd || isSubpath(cwd, wt.Path) {
			marker = ui.Current + " "
		}
		lines = append(lines, fmt.Sprintf("%s%s|%s|%s", marker, short, branch, wt.Path))
	}

	fzfCmd := exec.Command("fzf", "--ansi", "--no-sort", "--reverse",
		"--prompt=Switch to: ",
		"--header=↑↓ navigate  enter select  esc cancel",
		"--delimiter=|",
		"--with-nth=1,2",
		"--preview-window=hidden",
		"--query="+query)
	fzfCmd.Stdin = strings.NewReader(strings.Join(lines, "\n"))
	fzfCmd.Stderr = os.Stderr

	out, err := fzfCmd.Output()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			// exit code 130 = interrupted (Ctrl-C/Esc), 1 = no match
			if exitErr.ExitCode() == 130 || exitErr.ExitCode() == 1 {
				return "", nil
			}
		}
		return "", fmt.Errorf("fzf error: %w", err)
	}

	parts := strings.Split(strings.TrimSpace(string(out)), "|")
	if len(parts) < 3 {
		return "", fmt.Errorf("unexpected fzf output")
	}
	return parts[2], nil
}

func switchByName(ctx *cmdContext, worktrees []git.Worktree, cwd, name string) error {
	target, _, err := resolveWorktree(ctx, worktrees, name)
	if err != nil {
		return err
	}
	if target == "" {
		return fmt.Errorf("worktree not found: %s\n   Run wt list to see available worktrees", name)
	}

	savePreviousWorktree(cwd)
	ui.PrintCdHint(target)
	showSwitchSummary(target, ctx)
	return nil
}

// resolveWorktree finds a worktree path by name using the resolution chain.
// Returns (path, fuzzy, nil) on success — fuzzy=true when the match came from
// the substring-contains step (step 5), meaning the caller should confirm
// before destructive actions. Returns ("", false, nil) when no match is found.
// When several worktrees match, it opens fzf on them if it can, and
// otherwise returns an error that lists them.
func resolveWorktree(ctx *cmdContext, worktrees []git.Worktree, name string) (string, bool, error) {
	matches, fuzzy := matchWorktrees(ctx, worktrees, name)
	switch len(matches) {
	case 0:
		return "", false, nil
	case 1:
		if fuzzy {
			ui.DimF("Fuzzy matched: %s → %s\n", name, ctx.shortName(matches[0].Path))
		}
		return matches[0].Path, fuzzy, nil
	}

	_, fzfErr := exec.LookPath("fzf")
	if fzfErr == nil && isatty.IsTerminal(os.Stdin.Fd()) {
		target, err := pickWorktree(ctx, matches, "", name)
		if err != nil {
			return "", false, err
		}
		if target == "" {
			fmt.Println("Cancelled")
			return "", false, errSilent
		}
		return target, false, nil
	}

	var names []string
	for _, m := range matches {
		names = append(names, "     "+ctx.shortName(m.Path))
	}
	return "", false, fmt.Errorf("%q matches more than one worktree:\n%s\n   Use a longer name", name, strings.Join(names, "\n"))
}

// matchWorktrees returns the worktrees that match name at the first step of
// the resolution chain that matches any. fuzzy is true for step 5 matches.
func matchWorktrees(ctx *cmdContext, worktrees []git.Worktree, name string) ([]git.Worktree, bool) {
	// 1. Exact match with configured prefix
	if exact := ctx.worktreePath(name); isDir(exact) {
		return []git.Worktree{{Path: exact}}, false
	}

	// 2. Main repo match (base branch name, "main", "master", or repo name)
	if name == ctx.RepoName || ctx.isBaseBranch(name) {
		return []git.Worktree{{Path: ctx.MainWorktree}}, false
	}

	// 3. Branch name match (exact match against git branch)
	for _, wt := range worktrees {
		if wt.Branch == name {
			return []git.Worktree{wt}, false
		}
	}

	// 4. Suffix match
	var matches []git.Worktree
	for _, wt := range worktrees {
		base := filepath.Base(wt.Path)
		if strings.HasSuffix(base, "-"+name) || strings.HasSuffix(base, "/"+name) {
			matches = append(matches, wt)
		}
	}
	if len(matches) > 0 {
		return matches, false
	}

	// 5. Fuzzy match (contains) — checks both short name and branch
	nameLower := strings.ToLower(name)
	for _, wt := range worktrees {
		short := ctx.shortName(wt.Path)
		if strings.Contains(strings.ToLower(short), nameLower) ||
			strings.Contains(strings.ToLower(wt.Branch), nameLower) {
			matches = append(matches, wt)
		}
	}
	return matches, true
}

func showSwitchSummary(path string, ctx *cmdContext) {
	short := ctx.shortName(path)
	branch, _ := git.CurrentBranchIn(path)
	isBase := ctx.isBaseBranch(branch)

	fmt.Printf("%s %s", ui.Yellow(ui.Current), short)

	if branch != short && !isBase {
		fmt.Printf("  %s", ui.Dim(branch))
	}

	isBehind := false
	if !isBase {
		ab, err := git.GetAheadBehindIn(path, ctx.baseRef())
		if err == nil {
			if ab.Behind > 0 {
				fmt.Printf("  %s", ui.Yellow(fmt.Sprintf("⚠ %d behind", ab.Behind)))
				isBehind = true
			} else if ab.Ahead > 0 {
				fmt.Printf("  %s", ui.Green(ui.Pass))
			}
		}
	}

	fmt.Println()

	if !isBase {
		if isBehind {
			ui.PrintCTA("wt rebase", "wt init")
		} else {
			ui.PrintCTA("wt init")
		}
	}
}
package cmd

import (
	"fmt"

	"github.com/mvwi/wt/internal/git"
	"github.com/mvwi/wt/internal/github"
	"github.com/mvwi/wt/internal/ui"
	"github.com/spf13/cobra"
)

var submitCmd = &cobra.Command{
	Use:     "submit",
	GroupID: groupSync,
	Short:   "Rebase on base branch + push to remote",
	Long: `Rebase the current branch onto the base branch, then push to remote.

Uses --force-with-lease for safety (fails if remote has unexpected commits).
Cannot submit the base branch (use git push directly).`,
	Example: `  wt submit              Rebase + push current branch
  wt submit --continue   Resume after resolving rebase conflicts
  wt submit --abort      Abort rebase and cancel push`,
	RunE: runSubmit,
}

var (
	submitContinueFlag bool
	submitAbortFlag    bool
)

func init() {
	submitCmd.Flags().BoolVar(&submitContinueFlag, "continue", false, "resume after resolving conflicts")
	submitCmd.Flags().BoolVar(&submitAbortFlag, "abort", false, "abort and restore state")
	rootCmd.AddCommand(submitCmd)
}

func runSubmit(cmd *cobra.Command, args []string) error {
	ctx, err := newContext()
	if err != nil {
		return err
	}

	branch, err := git.CurrentBranch()
	if err != nil {
		return fmt.Errorf("not in a git repository or detached HEAD\n   Run this from inside a worktree")
	}

	if ctx.isBaseBranch(branch) {
		return fmt.Errorf("cannot submit the base branch (%s)\n   Switch to a feature worktree, or use git push directly", branch)
	}

	// Delegate to rebase first
	if err := runRebaseWith(rebaseOpts{
		continueRebase: submitContinueFlag,
		abort:          submitAbortFlag,
	}); err != nil {
		return err
	}

	// If rebase was just --abort or still in conflict, don't push
	if submitAbortFlag {
		return nil
	}
	inProgress, _ := git.IsRebaseInProgress()
	if inProgress {
		return nil
	}

	expectedUpstream := ctx.Config.Remote + "/" + branch
	actualUpstream := git.Upstream()

	// Push
	fmt.Println()
	head, _ := git.RevParseHead()
	remoteHead, _ := git.Run("rev-parse", "--verify", "--quiet", expectedUpstream)
	pushed := true
	switch {
	case actualUpstream == expectedUpstream && head != "" && head == remoteHead:
		pushed = false
		fmt.Printf("Nothing to push %s %s already matches your branch\n", ui.Dash, expectedUpstream)
	case actualUpstream == expectedUpstream:
		fmt.Println("Pushing to remote…")
		if err := git.PushForceWithLease(); err != nil {
			// Likely "stale info": the remote moved since we last fetched.
			// After the fetch, a retry overwrites those remote commits.
			fmt.Println()
			ui.Warn("Push rejected %s the remote branch has commits you haven't fetched", ui.Dash)
			fmt.Println("  Fetching latest remote state…")
			if fetchErr := git.Fetch(ctx.Config.Remote, branch); fetchErr != nil {
				return fmt.Errorf("failed to fetch: %w", fetchErr)
			}
			if ok, err := ui.ConfirmDiscard("Overwrite the remote commits?", false); !ok {
				if err != nil {
					return fmt.Errorf("push rejected: %s has commits you don't have\n   Check them with: git log HEAD..%s", expectedUpstream, expectedUpstream)
				}
				return fmt.Errorf("push cancelled")
			}
			fmt.Println()
			fmt.Println("Pushing to remote…")
			if err := git.PushForceWithLease(); err != nil {
				return fmt.Errorf("failed to push to remote: %w", err)
			}
		}
	default:
		fmt.Println("Pushing to remote…")
		if actualUpstream != "" {
			fmt.Printf("(fixing upstream: %s → %s)\n", actualUpstream, expectedUpstream)
		} else {
			fmt.Println("(setting upstream for new branch)")
		}
		if err := git.PushSetUpstream(ctx.Config.Remote); err != nil {
			return fmt.Errorf("failed to push to remote: %w", err)
		}
	}
	if pushed {
		fmt.Println()
		ui.Success("Submitted!")
	}

	if git.HasChanges() {
		fmt.Println("Note: uncommitted changes stay local. Commit them to include them.")
	}

	if !github.IsAvailable() {
		return nil
	}
	pr, err := github.GetPRForBranch(branch)
	switch {
	case err != nil:
		// No PR info (e.g. not a GitHub remote); say nothing.
	case pr == nil:
		fmt.Println()
		fmt.Printf("No open PR for this branch. Create one: %s\n", ui.Cyan("gh pr create"))
		ui.PrintCTA("gh pr create")
	case ui.IsTTY():
		fmt.Println()
		if ui.Confirm("Watch PR status?", true) {
			fmt.Println()
			return runWatch(cmd, nil)
		}
	default:
		ui.PrintCTA("wt watch")
	}
	return nil
}

